package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamAbhinayaRasaBank1 {
    private const val T = "නාට්‍ය ශාස්ත්‍රය, චතුර්විධ අභිනය හා නව රසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය නර්තන හා නාට්‍ය කලාවේ ඉපැරණිතම මූලික ශාස්ත්‍රීය ග්‍රන්ථය වන 'නාට්‍ය ශාස්ත්‍රය' රචනා කළ මුනිවරයා කවුද?", "භරත මුනිවරයා", "නන්දිකේශ්වර", "කාලිදාස", "වාල්මීකි", "භරත මුනිවරයා විසින් රචිත නාට්‍ය ශාස්ත්‍රය පෙරදිග රංග කලාවේ පස්වන වේදය ලෙස සැලකේ."),
        q("පෙරදිග නර්තන කලාවේ ප්‍රකාශන මාධ්‍යයන් හතර හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "චතුර්විධ අභිනය", "පංචතූර්ය නාදය", "සප්ත ස්වරය", "ත්‍රිවිධ රත්නය", "අදහස් හා හැඟීම් ප්‍රේක්ෂකයා වෙත සන්නිවේදනය කරන ප්‍රධාන ක්‍රම හතර චතුර්විධ අභිනයයි."),
        q("චතුර්විධ අභිනයට අයත් ප්‍රධාන අභිනයන් හතර මොනවාද?", "ආංගික, වාචික, ආහාර්ය සහ සාත්වික", "පතක, ත්‍රිපතක, මයුර සහ මුෂ්ටි", "තානම, කවිය, කස්තිරම සහ අඩව්ව", "උඩරට, පහතරට, සබරගමු සහ ජන", "ශරීර චලන, වචන, වෙස් ගැන්වීම් හා මානසික භාවයන් මෙම සතර අභිනයෙන් දැක්වේ."),
        q("ශරීරයේ අත්, පා, හිස, ඇස් ආදී අංග ප්‍රත්‍යංග චලනය කරමින් අදහස් ප්‍රකාශ කිරීම හඳුන්වන අභිනය කුමක්ද?", "ආංගික අභිනය", "වාචික අභිනය", "ආහාර්ය අභිනය", "සාත්වික අභිනය", "නර්තනයේ සියලු ශාරීරික චලන හා හස්ත මුද්‍රා ආංගික අභිනය යටතට ගැනේ."),
        q("කථනය, දෙබස්, කවි ගායනය හා උච්චාරණය මගින් භාවයන් ප්‍රකාශ කිරීම හඳුන්වන්නේ කුමන අභිනය ලෙසද?", "වාචික අභිනය", "ආංගික අභිනය", "සාත්වික අභිනය", "ආහාර්ය අභිනය", "වන්නම් කවි ගැයීම, කෝලම් හා සන්නි සංවාද වාචික අභිනයට නිදසුන් වේ."),
        q("රංග වස්ත්‍ර, ආභරණ, වේදිකා සැරසිලි, ආලෝකකරණය සහ අංග රචනය අයත් වන්නේ කුමන අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "ආංගික අභිනයට", "සාත්වික අභිනයට", "උඩරට වෙස් ඇඳුම හා පහතරට වෙස්මුහුණු ආහාර්ය අභිනයේ කැපී පෙනෙන උදාහරණ වේ."),
        q("සිතේ ඇති වන සැබෑ මානසික හැඟීම නිසා ඉබේම සිරුරේ ඇතිවන කඳුළු, වෙව්ලීම්, රෝමෝද්ගමනය වැනි ලක්ෂණ කුමන අභිනයද?", "සාත්වික අභිනය", "ආහාර්ය අභිනය", "ආංගික අභිනය", "වාචික අභිනය", "සාත්වික අභිනය රංගනයක ඉහළම ජීවමාන හා හදවතට දැනෙන ස්වාභාවික ප්‍රකාශනයයි."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව ප්‍රධාන සෞන්දර්ය රසයන් කීයක් දක්වා ඇත්ද (පසුව ශාන්ත රසය සමඟ)?", "නව රසයකි (9)", "සතර රසයකි (4)", "සය රසයකි (6)", "දොළොස් රසයකි (12)", "භරත මුනිවරයා මුලින් රස 8ක් දැක්වූ අතර පසුව ශාන්ත රසය එක්ව නව රසය සම්පූර්ණ විය."),
        q("ආදරය, සෙනෙහස හා ප්‍රේමය මුල් කරගත් රසය කුමක්ද?", "ශෘංගාර රසය", "වීර රසය", "රෞද්‍ර රසය", "භයානක රසය", "රති නමැති ස්ථායී භාවයෙන් උපදින ශෘංගාරය රස රාජයා ලෙසද හැඳින්වේ."),
        q("'ශෘංගාර' රසයට අදාළ ස්ථායී භාවය (මූලික මානසික හැඟීම) කුමක්ද?", "රති (ආදරය / ඇල්ම)", "හාස (සිනහව)", "ශෝක (දුක)", "ක්‍රෝධ (කෝපය)", "ප්‍රිය පුද්ගලයෙකු හෝ සුන්දර දෙයක් කෙරෙහි ඇති වන ඇල්ම රති භාවයයි."),
        q("සිනහව හා විනෝදය උපදවන 'හාස්‍ය රසයේ' ස්ථායී භාවය කුමක්ද?", "හාස (සිනහව)", "උත්සාහ", "භය", "ජුගුප්සා", "කෝලම් හා සන්නි නැටුම්වල විකට චරිත මගින් හාස්‍ය රසය බහුලව ජනිත කෙරේ."),
        q("දුක, වියෝව හා අනුකම්පාව මතු කරන 'කරුණා රසයේ' ස්ථායී භාවය කුමක්ද?", "ශෝක (දුක)", "විස්මය", "ක්‍රෝධ", "ශම", "වෙන්වීමක් හෝ විපතක් දුටු විට සිතේ හටගන්නා ශෝකය කරුණා රසය මවයි."),
        q("තදබල කෝපය, ආවේගය හා විනාශකාරී හැඟීම් ප්‍රකාශ කරන රසය කුමක්ද?", "රෞද්‍ර රසය", "ශාන්ත රසය", "හාස්‍ය රසය", "ශෘංගාර රසය", "'ක්‍රෝධ' ස්ථායී භාවයෙන් උපදින රෞද්‍ර රසය යුද හා සතුරු පහරදීම්වලදී පෙනේ."),
        q("අභීත බව, ධෛර්යය හා ජයග්‍රහණය සඳහා ඇති උද්යෝගය ප්‍රකාශ කරන රසය කුමක්ද?", "වීර රසය", "භයානක රසය", "භීභත්ස රසය", "කරුණා රසය", "'උත්සාහ' නමැති ස්ථායී භාවයෙන් වීර රසය උපදින අතර සිංහරාජ වන්නම මීට නිදසුනකි."),
        q("තැතිගැන්ම, බිය හා ත්‍රාසය ඇති කරන 'භයානක රසයේ' ස්ථායී භාවය කුමක්ද?", "භය (බිය)", "රති", "විස්මය", "උත්සාහ", "මහ සොහොන් සමයම හෝ වන මෘගයන් දුටු විට ඇතිවන හැඟීම භය භාවයයි."),
        q("පිළිකුල, අප්‍රසන්න බව හා ජුගුප්සාව දනවන නව රස අතර ඇති රසය කුමක්ද?", "භීභත්ස රසය", "අද්භූත රසය", "ශෘංගාර රසය", "ශාන්ත රසය", "අපිරිසිදු හෝ පිළිකුල් සහගත දර්ශනයකින් ඇති වන 'ජුගුප්සා' භාවය භීභත්ස රසයයි."),
        q("පුදුමය, ආශ්චර්යය හා විස්මය උපදවන 'අද්භූත රසයේ' ස්ථායී භාවය කුමක්ද?", "විස්මය", "ශෝක", "ක්‍රෝධ", "හාස", "අසාමාන්‍ය හා චමත්කාරජනක දෙයක් දුටු විට විස්මයෙන් අද්භූත රසය ඇති වේ."),
        q("සිතේ තැන්පත් බව, සංසිඳීම හා නිවීම පෙන්වන නවවන රසය කුමක්ද?", "ශාන්ත රසය", "රෞද්‍ර රසය", "වීර රසය", "හාස්‍ය රසය", "'ශම' හෙවත් නිවී සැනසීම ස්ථායී භාවය කරගත් ශාන්ත රසය අසදිස වන්නමේදී පෙනේ."),
        q("නව රස අතර 'වීර රසය' සංකේතවත් කරන සාම්ප්‍රදායික වර්ණය කුමක්ද?", "රන්වන් හෝ කහ පැහැය (ගෞර වර්ණය)", "තද කළු පැහැය", "නිල් පැහැය", "අළු පැහැය", "නාට්‍ය ශාස්ත්‍රයේ එක් එක් රසයට වෙනම වර්ණ හා අධිපති දෙවිවරුන් නම් කර ඇත."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව 'රෞද්‍ර රසය' සංකේතවත් කරන වර්ණය කුමක්ද?", "රතු පැහැය", "සුදු පැහැය", "ලා කොළ පැහැය", "රෝස පැහැය", "කෝපයෙන් මුහුණ රතු වීමේ ස්වභාවය අනුව රෞද්‍ර රසයට රතු වර්ණය හිමි වේ."),
        q("නව රස අතර 'ශාන්ත රසය' සංකේතවත් කරන සම්ප්‍රදායික වර්ණය කුමක්ද?", "පිරිසිදු සුදු පැහැය", "තද රතු පැහැය", "කළු පැහැය", "තැඹිලි පැහැය", "පවිත්‍රතාව හා මානසික නිවීම සුදු පැහැයෙන් සංකේතවත් කෙරේ."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'හාස්‍ය රසයට' හිමි සම්ප්‍රදායික වර්ණය ලෙස දක්වන්නේ කුමක්ද?", "සුදු පැහැය (හෝ ලා පැහැය)", "කළු පැහැය", "තද නිල් පැහැය", "දුඹුරු පැහැය", "සිනහවේදී මුහුණ පැහැපත් වීම සුදු වර්ණයෙන් නිරූපණය කෙරේ."),
        q("නව රස අතුරින් 'භයානක රසය' සංකේතවත් කරනු ලබන වර්ණය කුමක්ද?", "කළු පැහැය", "කහ පැහැය", "සුදු පැහැය", "ලා කොළ පැහැය", "අඳුර හා බියගුළු බව කළු පැහැයෙන් සංකේතවත් කෙරේ."),
        q("නර්තන කලාවේ ත්‍රිවිධ ප්‍රභේද ලෙස හඳුන්වනු ලබන 'නෘත්ත, නෘත්‍ය සහ නාට්‍ය' අතුරින් 'නෘත්ත' යනු කුමක්ද?", "තාලය හා රිද්මය මත පදනම් වූ ශුද්ධ නර්තනය", "දෙබස් හා කතා පුවතක් සහිත වේදිකා නාට්‍යය", "භාව හා අර්ථ නිරූපණය මුසු වූ ගායනය", "වෙස්මුහුණු පැළඳ කරන සාමාන්‍ය දෙබස් රංගනය", "උඩරට පා සරඹ හා කස්තිරම් ශුද්ධ නර්තනය හෙවත් නෘත්ත ගණයට අයත් වේ."),
        q("තාලය හා රිද්මය සමඟ 'භාව හා අර්ථ නිරූපණය' (අභිනය) එක්ව ඉදිරිපත් කරන නර්තනය කුමක්ද?", "නෘත්‍ය", "නෘත්ත", "සරල කථනය", "ගායනය පමණි", "වන්නම් කවි හා භරත පදම් රඟ දැක්වීමේදී තාලයට අමතරව අර්ථය පෙන්වන බැවින් එය නෘත්‍ය නම් වේ."),
        q("කථා පුවතක්, චරිත, දෙබස්, සංගීතය හා නර්තනය යන සියල්ල එක්වුණු පූර්ණ රංගනය කුමක්ද?", "නාට්‍ය", "නෘත්ත", "තානම", "සරඹ", "කෝලම්, සොකරි හා මනමේ වැනි සම්පූර්ණ රංගන නාට්‍ය ගණයට වැටේ."),
        q("පෙරදිග නර්තන කලාවේදී 'තාණ්ඩව' හා 'ලාස්‍ය' යන නර්තන ස්වරූප දෙකෙන් 'තාණ්ඩව' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ශිව දෙවියන් හා බැඳුණු ප්‍රබල, ජවසම්පන්න හා ශක්තිමත් නර්තන ශෛලිය", "පාර්වතී දේවිය හා බැඳුණු මෘදු, ලාලිත්‍යමය හා සුමට නර්තන ශෛලිය", "ළමා ජන ගී ආශ්‍රිත සරල කෙළි සෙල්ලම් රිද්ම නර්තන ශෛලිය", "වේදිකාවේ හිඳගෙන අභිනයෙන් තොරව කරන සාමූහික කවි ගායන ශෛලිය", "උඩරට වෙස් නැටුමේ වේගවත් අඩව් හා කස්තිරම් තාණ්ඩව ගුණයෙන් යුක්තය."),
        q("පාර්වතී දේවියගෙන් පැවත එන මෘදු, ලාලිත්‍යමය හා සෞම්‍ය නර්තන ශෛලිය හඳුන්වන්නේ කුමන නමකින්ද?", "ලාස්‍ය නර්තනය", "තාණ්ඩව නර්තනය", "රෞද්‍ර නර්තනය", "කෝලම් නර්තනය", "කළගෙඩි, මල් නැටුම් හා සබරගමු ලැසි චලන ලාස්‍ය ගුණයෙන් යුක්ත වේ."),
        q("නර්තනයේදී හිස චලනය කරන ආකාර පිළිබඳව ඉගැන්වෙන නාට්‍ය ශාස්ත්‍රීය කොටස කුමක්ද?", "ශිරෝ භේද", "දෘෂ්ටි භේද", "ග්‍රීවා භේද", "පාද භේද", "සම, උද්වාහිත, අධෝමුඛ ආදී වශයෙන් හිසේ චලන භේද නවයක් දක්වා ඇත."),
        q("නර්තනයේදී 'ඇස් සහ බැල්ම' හසුරුවන ආකාරය පිළිබඳව ඉගැන්වෙන කොටස කුමක්ද?", "දෘෂ්ටි භේද", "ශිරෝ භේද", "හස්ත මුද්‍රා", "තාල භේද", "සම, ආලෝකිත, සාචි ආදී දෘෂ්ටි භේද 8 ක් අභිනය දර්පණයේ සඳහන් වේ."),
        q("නර්තනයේදී 'බෙල්ල' චලනය කරන ආකාරය හඳුන්වන ශාස්ත්‍රීය පදය කුමක්ද?", "ග්‍රීවා භේද", "ශිරෝ භේද", "අංග භේද", "දෘෂ්ටි භේද", "සුන්දරී, තිරශ්චීනා, පරිවර්තිතා හා ප්‍රකම්පිතා ලෙස ග්‍රීවා භේද 4 ක් දැක්වේ."),
        q("සිතේ ඇති වන ප්‍රධාන ස්ථායී භාවයට ආධාර වන ක්ෂණිකව ඇති වී නැති වී යන උප හැඟීම් හඳුන්වන්නේ කෙසේද?", "ව්‍යභිචාරී හෙවත් සංචාරී භාව", "සාත්වික භාව", "ආහාර්ය භාව", "මූලික රස", "ලැජ්ජාව, සැකය, ආඩම්බරය වැනි තිස්තුනක් වූ සංචාරී භාව ස්ථායී භාවය පෝෂණය කරයි."),
        q("පෙරදිග රංග කලාවේ 'සාත්වික අභිනයට' අයත් අංග අට අතරින් එකක් වන 'ස්තම්භ' යනු කුමක්ද?", "අධික පුදුමය හෝ බිය නිසා ගල් ගැසී නිශ්චල වීම", "සිනහසීම", "උස් හඬින් ඇඬීම", "කවි ගායනා කිරීම", "ස්වේද, රෝමාංච, අශ්‍රැ හා ස්තම්භ ආදිය අෂ්ට සාත්වික භාවයන් වේ."),
        q("පෙරදිග නර්තන කලාවේ 'අභිනය දර්පණය' නමැති සුප්‍රසිද්ධ ග්‍රන්ථය රචනා කළ ආචාර්යවරයා කවුද?", "නන්දිකේශ්වර ආචාර්යතුමා", "භරත මුනිවරයා", "ශාරංගදේව", "තොටගමුවේ රාහුල හිමි", "හස්ත මුද්‍රා, ශිරෝ භේද හා දෘෂ්ටි භේද ඉගෙනීමට අභිනය දර්පණය මූලාශ්‍ර වේ."),
        q("නර්තන රස වින්දනයේදී 'සහෘදයා' යනුවෙන් හඳුන්වන්නේ කවුරුන්ද?", "නිර්මාණයේ රසය මනාව හඳුනාගෙන විඳින ප්‍රේක්ෂකයා", "වේදිකාවේ තිර අදින පුද්ගලයා", "බෙර හම සාදන්නා", "නැටුමට විරුද්ධ වන්නා", "කලාකරුවා උපදවන භාවය හදවතින් විඳගන්නා රසිකයා සහෘදයා වේ."),
        q("ශ්‍රී ලංකාවේ 'කෝලම්' හා 'සන්නි' නර්තන අංගයන්හිදී 'ආහාර්ය අභිනය' ප්‍රධාන වශයෙන්ම දැකිය හැක්කේ කුමකින්ද?", "විචිත්‍ර වෙස්මුහුණු හා රංග වස්ත්‍ර මගින්", "හඬ නඟා කෑගැසීමෙන්", "පාද පොළොවේ ගැසීමෙන්", "ඇස් කරකැවීමෙන්", "වෙස්මුහුණ පැළඳීමෙන් චරිතයේ ස්වභාවය බාහිරව ක්ෂණිකව නිරූපණය වේ."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව 'කරුණා රසය' සංකේතවත් කරන වර්ණය කුමක්ද?", "කපෝත වර්ණය (පරෙවි හෙවත් අළු පැහැය)", "තද රතු පැහැය", "රන්වන් පැහැය", "තද කළු පැහැය", "ශෝකී ස්වභාවය අනුව කරුණා රසයට පරෙවි පැහැය වෙන් කර ඇත."),
        q("නව රස අතර 'ශෘංගාර රසය' සංකේතවත් කරන වර්ණය ලෙස ශාස්ත්‍රීය ග්‍රන්ථවල දක්වා ඇත්තේ කුමක්ද?", "ශ්‍යාම හෙවත් තද නිල් පැහැය", "කපෝත හෙවත් පරෙවි පැහැය", "රක්ත හෙවත් තද රතු පැහැය", "ධවල හෙවත් සුදු පැහැය", "පෙරදිග සාම්ප්‍රදායික වර්ණ නියමය අනුව ශෘංගාර රසයට ශ්‍යාම වර්ණය අයත් වේ."),
        q("නව රස අතුරින් 'භීභත්ස රසය' සංකේතවත් කරන වර්ණය කුමක්ද?", "නිල් පැහැය", "රන්වන් පැහැය", "සුදු පැහැය", "රෝස පැහැය", "මහා කාල දෙවියන් අධිපතිත්වය දරන භීභත්ස රසයේ වර්ණය නීල වර්ණයයි."),
        q("නව රස අතුරින් 'අද්භූත රසය' සඳහා වෙන් කර ඇති වර්ණය කුමක්ද?", "පීත (කහ) වර්ණය", "කළු වර්ණය", "අළු වර්ණය", "දුඹුරු වර්ණය", "බ්‍රහ්ම දෙවියන් අධිපතිත්වය දරන අද්භූත රසයට කහ පැහැය නියම කර ඇත."),
        q("දේශීය නර්තන ක්ෂේත්‍රයේදී 'අභිනය පුහුණුව' සිසුන්ට අත්‍යවශ්‍ය වන්නේ ඇයි?", "නැටුම යාන්ත්‍රික ව්‍යායාමයක් නොවී හැඟීම්බර කලාවක් බවට පත් කිරීමට", "නැටුමේ බෙර තාලය හා වේගය අසීමිතව වැඩි කර පෙන්වීමට", "රංගනය අතරතුර බෙර වාදනය සම්පූර්ණයෙන්ම නතර කර තැබීමට", "සාම්ප්‍රදායික වෙස් ඇඳුම හා ආභරණ භාවිතයෙන් ඉවත් කිරීමට", "හදවතට දැනෙන සජීවී රංගනයක් සඳහා අභිනය අත්‍යවශ්‍ය වේ."),
        q("ශිරෝ භේද අතරින් හිස ඉහළට ඔසවා අහස හෝ උස් දෙයක් දෙස බැලීම හඳුන්වන්නේ කෙසේද?", "උද්වාහිත ශිරෝ භේදය", "අධෝමුඛ ශිරෝ භේදය", "සම ශිරෝ භේදය", "පරාවෘත්ත ශිරෝ භේදය", "සඳ, තරු, ගසක් මුදුන හෝ ආඩම්බර බව පෙන්වීමට උද්වාහිත හිස භාවිත කෙරේ."),
        q("ලැජ්ජාව, දුක හෝ පොළොව දෙස බැලීම පෙන්වීම සඳහා හිස පහළට නැඹුරු කිරීම කුමන ශිරෝ භේදයද?", "අධෝමුඛ ශිරෝ භේදය", "උද්වාහිත ශිරෝ භේදය", "ධුත ශිරෝ භේදය", "කම්පිත ශිරෝ භේදය", "පහළට නැඹුරු කළ හිසින් යටහත් පහත් බව හා ශෝකය පිළිබිඹු කෙරේ."),
        q("'යතෝ හස්තස් තතෝ දෘෂ්ටි:' යන අභිනය දර්පණ ශ්ලෝකයෙන් උගන්වන වැදගත් නර්තන නියමය කුමක්ද?", "අත යන දිශාවට ඇස යා යුතු බව", "අත ඉහළ යන විට ඇස පහළ බැලිය යුතු බව", "ඇස් පියාගෙන නැටිය යුතු බව", "හිස පිටුපසට හැරවිය යුතු බව", "අත්, ඇස්, සිත, භාව සහ රස එකට බැඳී පවතින ආකාරය මෙම සුප්‍රකට ශ්ලෝකයේ දැක්වේ."),
        q("නර්තනයකදී 'සාත්වික අභිනය' උපදවා ගැනීම සඳහා නැට්ටුවා කළ යුතු මූලික කාර්යය කුමක්ද?", "තමන් නිරූපණය කරන චරිතය හා භාවය සැබෑ ලෙසම සිතට ආරෝපණය කර ගැනීම", "පිටතින් පබළු මාල දහයක් පැළඳීම", "වේදිකාවේ විදුලි පහන් නිවීම", "බෙරය හයියෙන් ගැසීම", "සිතේ ඇතිවන අවංක හැඟීම මුහුණෙන් හා ශරීරයෙන් ස්වාභාවිකව මතු වේ."),
        q("චතුර්විධ අභිනයට අයත් 'ආංගික අභිනය' ප්‍රකාශ කිරීමේදී ප්‍රධාන වශයෙන් යොදාගන්නේ කුමක්ද?", "අත්, පා, හිස, කඳ සහ මුහුණේ ඉරියව්", "මයික්‍රෆෝන හා ගායනා", "වේදිකා තිර හා ආලෝකය", "වෙස් ඇඳුම් හා පබළු මාල", "ශාරීරික චලන මගින් අදහස් පැවසීම ආංගික අභිනයේ මූලික ස්වභාවයයි."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'වාචික අභිනයට' අයත් වන ප්‍රධාන ප්‍රකාශන මාධ්‍ය මොනවාද?", "කවි, ගීත, දෙබස්, යාතිකා සහ ස්වර උච්චාරණය", "හස්ත මුද්‍රා පමණක්", "ඇඳුම් පැළඳුම් සහ වෙස්මුහුණු", "ඇස්වලින් කඳුළු ගැලීම", "කටහඬ හා භාෂාව භාවිතයෙන් භාවයන් දැක්වීම වාචික අභිනයට අයත් වේ."),
        q("'ආහාර්ය අභිනය' මගින් රංග ශිල්පියෙකුට ලැබෙන ප්‍රධානතම ප්‍රායෝගික පහසුව කුමක්ද?", "බාහිර පෙනුමෙන් චරිත ස්වභාවය හඳුන්වා දීම", "වාද්‍ය භාණ්ඩවල නාද රටාව වෙනස් කිරීම", "නැටුමේ මූලික පාද චලන අඩු කිරීම", "ගායන කවිවල තාල වේගය පාලනය කිරීම", "වෙස්මුහුණ හා රංග වස්ත්‍ර චරිත නිරූපණය පහසු කරයි."),
        q("නව රස අතුරින් 'වීර රසයට' හිමි ස්ථායී භාවය කුමක්ද?", "උත්සාහය", "ශෝකය", "භය", "හාසය", "ධෛර්යය හා අභීත ක්‍රියාවන් සඳහා ඇති උත්සාහයෙන් වීර රසය උපදී."),
        q("නව රස අතුරින් 'රෞද්‍ර රසයේ' ස්ථායී භාවය කුමක්ද?", "ක්‍රෝධය", "රති", "විස්මය", "ශම", "තදබල කෝපය හා ආවේගය නිසා රෞද්‍ර රසය ජනිත වේ."),
        q("'භයානක රසයේ' සාම්ප්‍රදායික අධිපති දෙවියා ලෙස නාට්‍ය ශාස්ත්‍රයේ දක්වා ඇත්තේ කවුරුන්ද?", "කාල දෙවියන් (යම හෝ මහාකාල)", "විෂ්ණු දෙවියන්", "බ්‍රහ්ම දෙවියන්", "ඉන්ද්‍ර දෙවියන්", "නව රසවලට අධිපති දෙවිවරුන් නාට්‍ය ශාස්ත්‍රයේ සඳහන් කර ඇත."),
        q("'හාස්‍ය රසයේ' අධිපති දෙවියා ලෙස සාම්ප්‍රදායික ග්‍රන්ථවල දක්වා ඇත්තේ කවුරුන්ද?", "ප්‍රමථ ගණ", "ශිව දෙවියන්", "යම දෙවියන්", "විෂ්ණු දෙවියන්", "සිනහව හා විනෝදය ප්‍රමථ ගණ දෙවියන් හා සම්බන්ධ කර දක්වා ඇත."),
        q("'වීර රසයේ' අධිපති දෙවියා ලෙස සාම්ප්‍රදායිකව සලකන්නේ කුමන දෙවියන්ද?", "මහේන්ද්‍ර (ඉන්ද්‍ර) දෙවියන්", "යම දෙවියන්", "කාල දෙවියන්", "ප්‍රමථ ගණ", "දෙවියන්ගේ රජු වූ ඉන්ද්‍ර වීරත්වයේ හා ධෛර්යයේ සංකේතයයි."),
        q("'අද්භූත රසයේ' අධිපති දෙවියා ලෙස නාට්‍ය ශාස්ත්‍රයේ දක්වා ඇති දෙවියා කවුද?", "බ්‍රහ්ම දෙවියන් (හෝ ගන්ධර්ව)", "යම දෙවියන්", "රුද්‍ර දෙවියන්", "කාල දෙවියන්", "ආශ්චර්යමත් මැවීම් හා විස්මය බ්‍රහ්ම දෙවියන් සමඟ සම්බන්ධ වේ."),
        q("නර්තන කලාවේ 'තාණ්ඩව' ශෛලියට හිමි ශරීර චලන ලක්ෂණය කුමක්ද?", "ප්‍රබල, වේගවත්, කෝණික හා ශක්තිමත් චලන", "අතිශය මෘදු හා දුර්වල චලන", "නිශ්චලව බිම හිඳගෙන සිටීම", "ඇස් පියාගෙන සිටීම", "පුරුෂ ශක්තිය හා ජවය තාණ්ඩව නර්තනයෙන් ප්‍රකට කෙරේ."),
        q("නර්තනයේ 'ලාස්‍ය' ශෛලිය හඳුන්වා දුන් බව පුරාවෘත්තවල සඳහන් වන්නේ කවුරුන්ද?", "පාර්වතී දේවිය", "යම රජු", "රාවණ රජු", "මහ සොහොන් යකා", "ශිව දෙවියන්ගේ තාණ්ඩවයට ප්‍රතිවිරුද්ධව පාර්වතී දේවියගේ ලාස්‍ය නැටුම බිහි විය."),
        q("'අභිනය දර්පණය' කෘතියෙහි සඳහන් 'ශිරෝ භේද' සංඛ්‍යාව සම්පූර්ණයෙන් කීයක්ද?", "නවයකි (9)", "හතරකි (4)", "දෙකකි (2)", "විස්සකි (20)", "හිස චලනය කරන ආකාර නවයක් අභිනය දර්පණයේ විස්තර කර ඇත."),
        q("'අභිනය දර්පණය' ග්‍රන්ථයට අනුව 'දෘෂ්ටි භේද' සංඛ්‍යාව කීයක්ද?", "අටකි (8)", "තුනකි (3)", "දහසයකි (16)", "දෙකකි (2)", "ඇස් හා බැල්ම හසුරුවන ආකාර අටක් නාට්‍ය හා නර්තන අධ්‍යාපනයේ උගැන්වේ."),
        q("නර්තන ශාස්ත්‍රයේ 'ග්‍රීවා භේද' කීයක් උගන්වනු ලැබේද?", "හතරකි (4)", "අටකි (8)", "දහයකි (10)", "පහළොවකි (15)", "සුන්දරී, තිරශ්චීනා, පරිවර්තිතා හා ප්‍රකම්පිතා යනු ග්‍රීවා භේද හතරයි."),
        q("ශිරෝ භේද අතරින් 'සම' යන හිස පිහිටුවීම යොදාගන්නේ කුමන අවස්ථාවකදීද?", "නැටුම ඇරඹුමේදී හා සාමාන්‍ය නිශ්චල ඉරියව්වේදී", "තද කෝපයෙන් හා ආවේගයෙන් පහර දෙන අවස්ථාවේදී", "ප්‍රතික්ෂේප කිරීමට හිස දෙපසට වනන අවස්ථාවේදී", "වේගවත් කැරකීමකදී හිස පහළට නමා ගන්නා විට", "හිස කෙළින් සමබරව තබා ගැනීම සම ශිරෝ භේදයයි."),
        q("හිස දෙපසට ඇල කරමින් සුන්දරව නැටීම හෝ සැකය, ප්‍රේමය පෙන්වීම සිදු කරන ශිරෝ භේදය කුමක්ද?", "අංචිත ශිරෝ භේදය", "අධෝමුඛ ශිරෝ භේදය", "උද්වාහිත ශිරෝ භේදය", "කම්පිත ශිරෝ භේදය", "මෘදු ලාස්‍ය නර්තනවල අංචිත හිස චලනය ඉතා අලංකාරව යොදයි."),
        q("ග්‍රීවා භේද අතරින් 'තිරශ්චීනා' (ඉහළට හා දෙපසට නයෙකුගේ ගමන මෙන් බෙල්ල සෙලවීම) නිරූපණය කරන්නේ කුමක්ද?", "නයෙකුගේ ගමන, කඩු හරඹ හෝ ඉහළ පහළ සෙවීම", "නිදා ගැනීම", "අඬමින් සිටීම", "ගලක් මෙන් නිශ්චල වීම", "සර්ප ගමන් ආකාරයෙන් බෙල්ල දෙපසට චලනය කිරීම තිරශ්චීනා නම් වේ."),
        q("ග්‍රීවා භේද අතරින් 'පරිවර්තිතා' යන්නෙන් අදහස් කරන බෙල්ලේ චලනය කුමක්ද?", "අඩ සඳක හැඩයට දකුණට හා වමට බෙල්ල කරකැවීම", "බෙල්ල ඉදිරියට දිගු කිරීම", "හිස පහළට එල්ලා දැමීම", "බෙල්ල නොසොල්වා තැබීම", "ප්‍රේමණීය හැඟීම් හා ලාස්‍ය අලංකාරය පෙන්වීමට පරිවර්තිතා භාවිත කෙරේ."),
        q("දෘෂ්ටි භේද අතරින් 'ප්‍රලෝකිත' දෘෂ්ටිය යොදා ගන්නේ කුමන අවස්ථාවකදීද?", "දෙපසට වේගයෙන් බලමින් යමක් සෙවීමේදී හෝ කලබලය පෙන්වීමේදී", "නිශ්චලව භාවනා කරන විට", "සතුටින් සිනහසෙන විට", "ඇස් වසා ගන්නා විට", "අක්ෂි ගෝල දෙපසට චලනය කිරීම ප්‍රලෝකිත දෘෂ්ටියයි."),
        q("දෘෂ්ටි භේද අතරින් 'නිමීලිත' දෘෂ්ටිය (ඇස් අඩක් පියාගෙන සිටීම) නිරූපණය කරන්නේ කුමක්ද?", "භාවනාව, තපස, මරණය හෝ ගැඹුරු කල්පනාව", "තද කෝපය", "වේගවත් නැටුම", "පුදුමයට පත්වීම", "ශාන්ත හා අධ්‍යාත්මික භාවයන් දැක්වීමට නිමීලිත බැල්ම උපකාරී වේ."),
        q("නර්තන රංගනයකදී 'උපාංග' වලට අයත් 'ඇහිබැම' චලනය මගින් කළ හැකි ප්‍රධාන කාර්යය කුමක්ද?", "සියුම් මුහුණු හැඟීම් හා රස භාව තීව්‍ර කිරීම", "පාද තාලයේ මාත්‍රා වේගය පාලනය කිරීම", "හස්ත මුද්‍රාවල ඇඟිලි හැඩය වෙනස් කිරීම", "බෙර වාදනයේ පද අක්ෂර උච්චාරණය කිරීම", "මුහුණේ ප්‍රකාශන ශක්තිය වැඩි කිරීමට ඇහිබැම චලනය අතිශය වැදගත් වේ."),
        q("අෂ්ට සාත්වික භාව අතරින් 'වෛවර්ණ්‍ය' යන පදයෙන් අදහස් කරන්නේ කුමන ශාරීරික වෙනසද?", "භාවයන් නිසා මුහුණේ පැහැය වෙනස් වීම", "රංග වස්ත්‍රයේ වර්ණ රටා වෙනස් වීම", "කවි ගායනයේ කටහඬ උස් පහත් වීම", "නැටුමේදී දෙඅත් හිස මට්ටමින් එසවීම", "මානසික ආවේග නිසා රුධිර සංසරණය වෙනස් වී මුහුණ සුදුමැලි හෝ රතු වීම මෙයයි."),
        q("අෂ්ට සාත්වික භාව අතරින් 'ස්වරභේද' යනු කුමක්ද?", "හැඟීම් නිසා කටහඬ ගොත ගැසීම හෝ වෙව්ලීම", "කම්පනය නිසා දෙඅත් හා සිරුර වෙව්ලීම", "දැඩි ශෝකය නිසා දෑසින් කඳුළු ගැලීම", "ආවේගය නිසා සිරුරෙන් දහඩිය දැමීම", "හදවතට දැනෙන තදබල හැඟීමක් නිසා වචන පිටවීමේ සිදුවන වෙනස මෙයයි."),
        q("අෂ්ට සාත්වික භාව අතරින් 'වේපථු' හෙවත් කම්පනය යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "බිය, සීතල හෝ කෝපය නිසා සිරුර වෙව්ලීම", "නිශ්චලව සිටගැනීම", "සිනහසීම", "කතා නොකර සිටීම", "සැබෑ චිත්තවේගය ශරීරයෙන් ප්‍රකාශ වන ස්වාභාවික ලක්ෂණයකි."),
        q("අෂ්ට සාත්වික භාව අතරින් 'ප්‍රලය' යනු රංගනයේදී නිරූපණය කරන කුමන අවස්ථාවද?", "දැඩි ශෝකය හෝ කම්පනය නිසා සිහි මුර්ජා වී වැටීම", "වේගයෙන් උඩ පැනීම", "අත්පුඩි ගැසීම", "ගීත ගැයීම", "රංගනයේ උච්චතම භාවමය අවස්ථාවකදී ප්‍රලය සාත්වික භාවය පෙන්වයි."),
        q("පෙරදිග නර්තනයේදී 'නෘත්ත' නර්තනය සඳහා හොඳම දේශීය උදාහරණය කුමක්ද?", "උඩරට පා සරඹ, ගොඩ සරඹ සහ කස්තිරම්", "සන්නි යකුමේ දෙබස් කොටස", "සොකරි නාටකයේ කථාව", "කවි ගායනය පමණි", "අර්ථයක් නොකියා රිද්මමය අලංකාරය පමණක් පෙන්වීම නෘත්තයයි."),
        q("'නෘත්‍ය' යන නර්තන අංගයට වඩාත්ම ගැළපෙන දේශීය උදාහරණය තෝරන්න.", "වන්නම් කවිවල අදහස හස්ත මුද්‍රා හා අභිනයෙන් නැටීම", "දණ්ඩියම් කඳ අල්ලා පා සරඹ ගැසීම", "කිසිදු චලනයක් නැතිව පොතක් කියවීම", "බෙර වාදනය පමණක් කිරීම", "තාලය සමඟ අර්ථ නිරූපණය මුසු වූ විට නෘත්‍යය බිහි වේ."),
        q("'නාට්‍ය' යන පූර්ණ රංගන අංගයට අයත් වන ශ්‍රී ලාංකේය සාම්ප්‍රදායික කලාංගය කුමක්ද?", "කෝලම්, සොකරි සහ නාඩගම්", "තනි පා සරඹයක්", "මඟුල් බෙර වාදනය", "තාලම්පට තනි වාදනය", "දෙබස්, චරිත, නැටුම් හා සංගීතය සියල්ල නාට්‍යයේ අඩංගු වේ."),
        q("භරත මුනිවරයා 'නාට්‍ය ශාස්ත්‍රය' රචනා කිරීමේදී ගීත හා සංගීතය ලබා ගත්තේ කුමන වේදයෙන්ද?", "සාම වේදයෙන්", "ඍග් වේදයෙන්", "යජුර් වේදයෙන්", "අථර්ව වේදයෙන්", "සාම වේදය ඉන්දියානු සංගීතයේ මූලාශ්‍රය ලෙස සැලකේ."),
        q("'නාට්‍ය වේදය' සැකසීමේදී පාඨ්‍යය හෙවත් වචන හා කථනය ලබා ගත් වේදය කුමක්ද?", "ඍග් වේදය", "සාම වේදය", "යජුර් වේදය", "අථර්ව වේදය", "සතර වේදයන්ගේම උතුම් අංග එක් කොට නාට්‍ය කලාව නිර්මාණය විය."),
        q("දේශීය නර්තනයේදී 'වීර රසය' මතු වන පහතරට හෝ සබරගමු අංගයකට උදාහරණයක් කුමක්ද?", "සුරපති හෝ දෙවොල් දෙවියන්ගේ රණකාමී පාලි නැටුම්", "ගොළු සන්නියේ විකට රංගනය", "කළගෙඩි නැටුම", "ගොයම් නැටුම", "තේජස හා වීරත්වය ප්‍රකාශ කරන සියලු පියවර වීර රසය දනවයි."),
        q("නව රස අතුරින් 'භීභත්ස රසය' ඇති වන අවස්ථාවකට දේශීය රංග කලාවෙන් දිය හැකි නිදසුන කුමක්ද?", "සන්නි යකුමේ විකෘති රෝග ස්වරූප දැක්වීම", "මල් යහන් පූජාවේ ලාලිත්‍ය නැටුම", "හංස වන්නමේ සෞම්‍ය ගමන් රංගනය", "ලී කෙළි ජන නැටුමේ රිද්ම රංගනය", "අප්‍රසන්න බව හා පිළිකුල ප්‍රේක්ෂකයා තුළ ඇති කර රෝග භීතිය පහ කිරීම මෙහිදී පෙනේ."),
        q("නව රස අතුරින් 'ශාන්ත රසය' වඩාත් මැනවින් ප්‍රකාශ වන දේශීය නැටුම් අංගයක් කුමක්ද?", "අසදිස වන්නමේ බුදු ගුණ හා මල් පූජා නැටුම", "හේවා කෝලමේ විකට යුද්ධ සටන් අංගය", "මහ සොහොන් සමයමේ භයංකාර රංගනය", "සිංහරාජ වන්නමේ වීර පිම්ම හා අඩව්ව", "තැන්පත් බව, ශ්‍රද්ධාව හා මානසික සන්සුන් බව ශාන්ත රසයේ ලක්ෂණයයි."),
        q("'විභාව' කොටස් දෙකකට බෙදනු ලැබේ. ඒවා මොනවාද?", "ආලම්බන විභාව සහ උද්දීපන විභාව", "තාණ්ඩව සහ ලාස්‍ය", "ආංගික සහ වාචික", "සුසිර සහ ඝන", "රසය උපදවන පුද්ගලයා ආලම්බන වන අතර පරිසර පසුබිම උද්දීපන වේ."),
        q("සඳ එළිය, සිසිල් සුළඟ හා මල් පිපුණු උයන වැනි පරිසර සාධක නාට්‍ය ශාස්ත්‍රයේදී හඳුන්වන්නේ කෙසේද?", "උද්දීපන විභාව", "සාත්වික භාව", "සංචාරී භාව", "ආංගික අභිනය", "ප්‍රේමය හෝ ශෝකය වැනි භාවයන් වැඩි දියුණු කරන බාහිර පරිසරය උද්දීපන විභාවයි."),
        q("'සංචාරී භාව' (ව්‍යභිචාරී භාව) ගණන නාට්‍ය ශාස්ත්‍රයේ කීයක් ලෙස දක්වා ඇත්ද?", "තිස් තුනකි (33)", "නවයකි (9)", "හතරකි (4)", "අටකි (8)", "මුහුදේ රැළි මෙන් ස්ථායී භාවය තුළ මතු වී බැස යන හැඟීම් සංචාරී භාව 33 කි."),
        q("නර්තනයකදී 'සාත්වික අභිනය' දුර්වල වුවහොත් රංගනයට සිදු වන්නේ කුමක්ද?", "රංගනය හැඟීම් රහිත යාන්ත්‍රික චලන පෙළක් වීම", "රංග වස්ත්‍රයේ අලංකාර හැඩය වෙනස් වීම", "බෙර වාදනයේ මාත්‍රා වේගය අධික වීම", "වේදිකාවේ ප්‍රමාණය පුළුල් වී පෙනීම", "සැබෑ හැඟීමෙන් තොර නර්තනය ප්‍රේක්ෂක හදවත ස්පර්ශ නොකරයි."),
        q("චතුර්විධ අභිනයේදී 'වේදිකා සැරසිලි' හා 'ගොක් කොළ තොරණ' අයත් වන්නේ කුමන අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "සාත්වික අභිනයට", "ආංගික අභිනයට", "රංගනයට උපකාරී වන සියලු බාහිර සැරසිලි ආහාර්ය අභිනය යටතට ගැනේ."),
        q("පෙරදිග නර්තනයේ 'අංග' යටතට ගැනෙන ප්‍රධාන ශරීර කොටස් හය මොනවාද?", "හිස, අත්, පපුව, පාර්ශ්ව, ඉණ සහ පාද", "ඇස්, ඇහිබැම, නාසය, කන්, තොල් සහ නිකට", "උරහිස්, වැලමිට, මැණික් කටුව, කලවා සහ දණහිස්", "ඇඟිලි පුරුක්, වළලුකර සහ යටිපතුල් කොටස්", "අභිනය දර්පණය අනුව ශරීරය අංග, ප්‍රත්‍යංග හා උපාංග ලෙස බෙදේ."),
        q("'ප්‍රත්‍යංග' ගණයට අයත් වන ශරීර කොටස් කිහිපයක් නම් කරන්න.", "උරහිස්, බාහු, වැලමිට, කලවා සහ දණහිස්", "හිස, නළල, ඇස්, කන් සහ නිකට පමණි", "ඇස්, ඇහිබැම, නාසය සහ තොල් පමණි", "දෙඅත්වල නියපොතු සහ හිසකෙස් පමණි", "අංග එකිනෙක සම්බන්ධ කරන හා චලනයට උපකාරී වන කොටස් ප්‍රත්‍යංග වේ."),
        q("නර්තන රංගනයකදී 'ලෝක ධර්මී' හා 'නාට්‍ය ධර්මී' යන ක්‍රම දෙකෙන් දේශීය වන්නම් නැටීම අයත් වන්නේ කුමකටද?", "නාට්‍ය ධර්මී අභිනයට", "ලෝක ධර්මී අභිනයට", "බටහිර ශෛලියට", "ව්‍යායාම පමණකට", "විශේෂිත තාල හා සංකේතාත්මක චලන නියමයන්ට අනුව නැටීම නාට්‍ය ධර්මී වේ."),
        q("නර්තනයකදී 'හාස්‍ය රසය' මතු කරන 'විකට චරිතයක්' රඟ දක්වන විට අත්‍යවශ්‍ය වන ශිල්පීය සීමාව කුමක්ද?", "සමාජ සදාචාරය හා කලා ගෞරවය නොඉක්මවා හාස්‍යය ඉදිරිපත් කිරීම", "ප්‍රේක්ෂකයන්ට අපහාස කිරීම", "වැදි අයුරින් කෑගැසීම", "බෙර වාදකයාට බාධා කිරීම", "සංවර උපහාසය උසස් කලා රසයක් ගෙන එයි."),
        q("ශෘංගාර රසය කොටස් දෙකකට බෙදා දක්වයි. ඒවා මොනවාද?", "සම්භෝග ශෘංගාරය සහ විප්‍රලම්භ ශෘංගාරය", "තාණ්ඩව අභිනය සහ ලාස්‍ය අභිනය", "ආලම්බන විභාවය සහ උද්දීපන විභාවය", "සාත්වික භාවය සහ සංචාරී භාවය", "ප්‍රේමවන්තයන් එක්ව සිටින අවස්ථාව හා විරහව යන දෙකම ශෘංගාරයේ අංශ වේ."),
        q("නව රස අතුරින් 'කරුණා රසය' හා 'විප්‍රලම්භ ශෘංගාරය' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "විප්‍රලම්භයේ යළි හමුවීමේ පැතුම හා කරුණාවේ ස්ථිර ශෝකය පවතී", "විප්‍රලම්භයේ හාස්‍ය රසය හා කරුණාවේ වීර රසය පවතී", "කරුණාවේ ක්‍රෝධ හැඟීම් හා විප්‍රලම්භයේ භය පවතී", "රස දෙකෙහිම පවතින්නේ යුද ජයග්‍රහණය පිළිබඳ උද්යෝගයයි", "හැඟීම්වල සියුම් වෙනස නාට්‍ය ශාස්ත්‍රයේ ඉතා නිවැරදිව විග්‍රහ කර ඇත."),
        q("නර්තනයේදී 'දෑස්' චලනය නොකර අත් පා පමණක් චලනය කළහොත් ඇති වන අඩුව කුමක්ද?", "භාව ප්‍රකාශනය අසම්පූර්ණ වී රංග ආකර්ෂණය හීන වීම", "බෙර වාදනයේ මාත්‍රා වේගය පාලනයෙන් ගිලිහී යාම", "පාද චලන හා මණ්ඩි සමබරතාව සම්පූර්ණයෙන් බිඳ වැටීම", "රංග වස්ත්‍රයේ හා ආභරණවල හැඩය නොපෙනී යාම", "ඇස යනු මනසේ කැඩපත බැවින් අත් චලන සමඟ දෘෂ්ටිය අනිවාර්යයෙන් ගමන් කළ යුතුය."),
        q("'යතෝ දෘෂ්ටිස් තතෝ මන:' යන්නෙන් කියැවෙන නර්තන මූලධර්මය කුමක්ද?", "ඇස යොමු වන තැනට සිත යොමු විය යුතු බව", "සිත වෙනතක තබා නැටිය යුතු බව", "ඇස් පියාගෙන සිටිය යුතු බව", "පිටුපස බලා නැටිය යුතු බව", "ඒකාග්‍රතාව හා භාවෝත්පත්තිය සඳහා ඇස, අත, සිත එකම තැනක රැඳිය යුතුය."),
        q("'යතෝ මනස් තතෝ භාව:' යන නර්තන නියමයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "සිත යොමු වන තැන සැබෑ හැඟීම (භාවය) උපදින බව", "හැඟීමක් නැතිව නැටීම", "බෙරය පමණක් වැයීම", "වෙස්මුහුණ මාරු කිරීම", "අභිනය දර්පණයේ එන මෙම ශ්ලෝක පෙළ නර්තනයේ ආධ්‍යාත්මික නීතියයි."),
        q("නව රස විග්‍රහයේදී 'නරඹන්නා තුළ' ඇති වන ප්‍රතිඵලය 'රසය' නම්, 'නැට්ටුවා තුළ' ඇති විය යුත්තේ කුමක්ද?", "භාවය", "තාලම්පට", "බෙර කඳ", "වේදිකා ආලෝකය", "නැට්ටුවා ප්‍රකාශ කරන භාවය ප්‍රේක්ෂකයා තුළ රසය බවට පරිවර්තනය වේ."),
        q("උසස් පෙළ හා සාමාන්‍ය පෙළ නර්තන සිසුවෙකුට 'චතුර්විධ අභිනය' ඉගෙනීමෙන් ලැබෙන ප්‍රායෝගික ප්‍රයෝජනය කුමක්ද?", "ඕනෑම නර්තන අංගයක් පරිපූර්ණව ඉදිරිපත් කිරීම", "බෙර කඳන් හා වෙස්මුහුණු පමණක් කැපීම", "ලිඛිත කවි පොත් පමණක් පිටපත් කිරීම", "වාද්‍ය භාණ්ඩවල සම් බැඳ අලුත්වැඩියා කිරීම", "ශරීරය, කටහඬ, ඇඳුම හා හැඟීම් මනාව සංයෝජනය කිරීමට මෙම දැනුම ඉවහල් වේ.")
    )
}
